using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using System.Linq;
namespace KingOrDeath {
    public class AssetShowcase:MonoBehaviour {
        public GameObject[] prefabs;public Transform[] subjects;public Camera view;public int selected;public string clip="Idle";
        Vector3 focus;float distance=12,yaw=32,pitch=26;bool verifying;List<string> results=new List<string>();
        public static string StateName(string clipName,string asset){int start=clipName.LastIndexOf(asset+"_",StringComparison.Ordinal);return start>=0?clipName.Substring(start+asset.Length+1):clipName.Substring(clipName.LastIndexOf('|')+1);}
        public static void Capture(Camera camera,string path){var previous=camera.targetTexture;var active=RenderTexture.active;var target=new RenderTexture(1600,900,24);camera.targetTexture=target;camera.Render();RenderTexture.active=target;var texture=new Texture2D(1600,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1600,900),0,0);texture.Apply();File.WriteAllBytes(path,texture.EncodeToPNG());camera.targetTexture=previous;RenderTexture.active=active;Destroy(texture);Destroy(target);}
        IEnumerator Watchdog(string output){yield return new WaitForSecondsRealtime(180);results.Add("FAIL: Showcase watchdog expired");File.WriteAllLines(Path.Combine(output,"AssetRuntimeValidation.txt"),results);Application.Quit(2);}
        void Awake(){Focus(0);}
        public void Focus(int index){selected=Mathf.Clamp(index,0,subjects.Length-1);var subject=subjects[selected];var lod=subject.GetComponent<LODGroup>();var rs=lod?lod.GetLODs()[0].renderers:subject.GetComponentsInChildren<Renderer>();var bounds=new Bounds(subject.position,Vector3.one);foreach(var r in rs)bounds.Encapsulate(r.bounds);focus=bounds.center;distance=Mathf.Max(2.2f,bounds.size.magnitude*1.2f);}
        void Update(){if(verifying)return;for(int i=0;i<subjects.Length&&i<9;i++)if(Input.GetKeyDown((KeyCode)((int)KeyCode.Alpha1+i)))Focus(i);if(Input.GetMouseButton(1)){yaw+=Input.GetAxis("Mouse X")*4;pitch=Mathf.Clamp(pitch-Input.GetAxis("Mouse Y")*3,4,80);}distance=Mathf.Clamp(distance-Input.mouseScrollDelta.y*.5f,1.5f,70);CameraPose();}
        void CameraPose(){view.transform.rotation=Quaternion.Euler(pitch,yaw+180,0);view.transform.position=focus-view.transform.forward*distance;}
        public void Play(string state){clip=state;foreach(var a in subjects[selected].GetComponentsInChildren<Animator>())if(a.runtimeAnimatorController&&a.HasState(0,Animator.StringToHash(state)))a.CrossFade(state,.15f);}
        void OnGUI(){GUI.Box(new Rect(12,12,570,112),"KING OR DEATH · ASSET SHOWCASE 001");GUI.Label(new Rect(25,40,540,25),(selected+1)+" / "+subjects.Length+"   "+subjects[selected].name+"   |   RMB orbit · wheel zoom · 1–6 select");var actor=subjects[selected].GetComponentInChildren<Animator>();string[] states=actor&&actor.runtimeAnimatorController?actor.runtimeAnimatorController.animationClips.Select(c=>StateName(c.name,subjects[selected].name)).Distinct().ToArray():Array.Empty<string>();for(int i=0;i<states.Length;i++)if(GUI.Button(new Rect(24+i*77,78,75,26),states[i]))Play(states[i]);}
        IEnumerator Start(){
            var args=Environment.GetCommandLineArgs();int arg=Array.IndexOf(args,"-assetverify");if(arg<0)yield break;verifying=true;string output=args[arg+1];Directory.CreateDirectory(output);Application.runInBackground=true;StartCoroutine(Watchdog(output));yield return null;
            focus=new Vector3(11,2,5.5f);distance=44;pitch=48;CameraPose();yield return null;Capture(view,Path.Combine(output,"AllSixAssets_RTS.png"));pitch=26;
            for(int i=0;i<subjects.Length;i++){
                Focus(i);CameraPose();var group=subjects[i].GetComponent<LODGroup>();group.ForceLOD(0);yield return new WaitForSeconds(.5f);
                bool valid=group&&group.GetLODs().Length==3;int triangles=0;foreach(var r in group.GetLODs()[0].renderers){foreach(var m in r.sharedMaterials)valid&=m&&m.shader&&m.GetTexture("_BaseMap");var sk=r as SkinnedMeshRenderer;var mesh=sk?sk.sharedMesh:r.GetComponent<MeshFilter>()?.sharedMesh;if(mesh)triangles+=mesh.triangles.Length/3;else valid=false;}
                results.Add((valid?"PASS":"FAIL")+": "+subjects[i].name+" imported/rendered; LOD0 triangles="+triangles);
                Capture(view,Path.Combine(output,subjects[i].name+"_PlayMode.png"));yield return new WaitForSeconds(.3f);
                var animator=subjects[i].GetComponentInChildren<Animator>();if(animator&&animator.runtimeAnimatorController){var skin=group.GetLODs()[0].renderers.OfType<SkinnedMeshRenderer>().FirstOrDefault();var reference=new Mesh();if(skin)skin.BakeMesh(reference);var states=animator.runtimeAnimatorController.animationClips.Select(c=>{string n=c.name;return StateName(n,subjects[i].name);}).Distinct().ToArray();foreach(var state in states){Play(state);yield return new WaitForSeconds(.55f);bool exists=animator.HasState(0,Animator.StringToHash(state));bool deforms=state=="Idle";if(skin){var posed=new Mesh();skin.BakeMesh(posed);var a=reference.vertices;var b=posed.vertices;for(int v=0;v<Mathf.Min(a.Length,b.Length);v++)if((a[v]-b[v]).sqrMagnitude>.00001f){deforms=true;break;}Destroy(posed);}results.Add((exists&&deforms?"PASS":"FAIL")+": "+subjects[i].name+" Animator "+state+", skeletal deformation="+deforms);Capture(view,Path.Combine(output,subjects[i].name+"_"+state+".png"));yield return new WaitForSeconds(.1f);}Destroy(reference);Play("Idle");}
                for(int level=1;level<3;level++){group.ForceLOD(level);yield return new WaitForSeconds(.15f);Capture(view,Path.Combine(output,subjects[i].name+"_LOD"+level+".png"));yield return new WaitForSeconds(.15f);}group.ForceLOD(-1);
            }
            int soldier=Array.FindIndex(prefabs,p=>p.name=="KOD_Human_Swordsman");var spawned=new List<GameObject>();if(soldier>=0){for(int i=0;i<60;i++){var go=Instantiate(prefabs[soldier],new Vector3((i%10)*1.7f,0,-12-(i/10)*1.7f),Quaternion.identity);spawned.Add(go);var a=go.GetComponentInChildren<Animator>();if(a)a.Play("Walk");}focus=new Vector3(8,1,-16);distance=20;pitch=48;CameraPose();yield return new WaitForSeconds(2);var benchmark=new RenderTexture(1600,900,24);var probe=new Texture2D(1,1,TextureFormat.RGB24,false);view.targetTexture=benchmark;int frames=0;float start=Time.realtimeSinceStartup;while(Time.realtimeSinceStartup-start<5){view.Render();RenderTexture.active=benchmark;probe.ReadPixels(new Rect(0,0,1,1),0,0,false);RenderTexture.active=null;frames++;yield return null;}float elapsed=Time.realtimeSinceStartup-start;view.targetTexture=null;Destroy(benchmark);Destroy(probe);results.Add("MEASURED: 60 animated swordsmen, "+(frames/elapsed).ToString("F1")+" average FPS over "+elapsed.ToString("F2")+" seconds. "+SystemInfo.graphicsDeviceName+". 1600x900 explicit camera rendering with one-pixel GPU readback each frame; includes synchronization overhead, excludes gameplay AI. Not Unity Profiler or normal-window FPS.");Capture(view,Path.Combine(output,"SixtyAnimatedUnits.png"));yield return new WaitForSeconds(.3f);}
            File.WriteAllLines(Path.Combine(output,"AssetRuntimeValidation.txt"),results);Application.Quit(results.Exists(s=>s.StartsWith("FAIL"))?1:0);
        }
    }
}
